// csv-reader-speed-01 v9: Rust #![no_std] WASM (v128 SIMD) transducer.
// The WASM module (base64 below) parses the input exactly like csv-reader
// 1.0.0 (ported from solve.js v8) and writes the answer as UTF-8 JSON.
// run() returns the parsed answer (house driver). runRaw() returns the
// answer's JSON bytes (for a driver that writes answers.json directly).
import { Buffer } from 'node:buffer';

const WASM_B64 = '';

const wasmBytes = Buffer.from(WASM_B64, 'base64');
const instance = new WebAssembly.Instance(
  new WebAssembly.Module(wasmBytes),
  {},
);
const { memory, input_ptr, output_ptr, parse, parse_at, parse_fused_at } = instance.exports;
const IN_PTR = input_ptr();
const OUT_PTR = output_ptr();
const memU8 = new Uint8Array(memory.buffer);
const utf8 = new TextDecoder('utf-8');

// Max input the WASM input region holds, in UTF-16 code units.
const INPUT_CAP_UNITS = 4000000;

/** WASM memory view + output region start, for drivers that lay out several
 *  cases' JSON contiguously (see main-direct.ts). */
export const wasmMemU8 = memU8;
export const wasmOutPtr = OUT_PTR;

function parseToJsonBytes(text, header, outOff = 0) {
  const n = text.length;
  if (n > INPUT_CAP_UNITS) throw new Error('csv v9: input too large');
  const buf = Buffer.from(text, 'utf16le');
  memU8.set(buf, IN_PTR);
  const outLen = parse_at(n, header ? 1 : 0, outOff);
  return memU8.subarray(OUT_PTR + outOff, OUT_PTR + outOff + outLen);
}

/** csv-reader 1.0.0's answer for one case's input. */
export function run(input) {
  const text = String(input.text);
  const bytes = parseToJsonBytes(text, input.header === true);
  return JSON.parse(utf8.decode(bytes));
}

/** The answer's JSON bytes (a view into WASM memory: copy before the next call). */
export function runRaw(input) {
  const text = String(input.text);
  return parseToJsonBytes(text, input.header === true);
}

/** Parse and write the answer's JSON at OUT + outOff; returns its length.
 *  The bytes stay valid until the next parse call (they live in the WASM
 *  output region, so a driver can lay several cases out contiguously). */
export function runRawAt(input, outOff) {
  const text = String(input.text);
  return parseToJsonBytes(text, input.header === true, outOff).length;
}

const FUSED_OVERFLOW = 4294967295; // u32::MAX: EXTRA scratch ran low

function parseFusedToJsonBytes(text, header, outOff = 0) {
  const n = text.length;
  if (n > INPUT_CAP_UNITS) throw new Error('csv v9: input too large');
  const buf = Buffer.from(text, 'utf16le');
  memU8.set(buf, IN_PTR);
  let outLen = parse_fused_at(n, header ? 1 : 0, outOff);
  if (outLen === FUSED_OVERFLOW) {
    // EXTRA scratch ran low: fall back to the two-phase parse.
    outLen = parse_at(n, header ? 1 : 0, outOff);
  }
  return memU8.subarray(OUT_PTR + outOff, OUT_PTR + outOff + outLen);
}

/** Fused single-pass parse; writes the answer's JSON at OUT + outOff and
 *  returns its length. Bytes stay valid until the next parse call. */
export function runFusedAt(input, outOff) {
  const text = String(input.text);
  return parseFusedToJsonBytes(text, input.header === true, outOff).length;
}

/** The fused answer's JSON bytes (a view into WASM memory: copy before the
 *  next call). Falls back to the two-phase parse on EXTRA overflow. */
export function runFused(input) {
  const text = String(input.text);
  return parseFusedToJsonBytes(text, input.header === true);
}
